import json, sys, time, urllib.parse
from concurrent.futures import ThreadPoolExecutor

BASE = "https://web.archive.org/cdx/search/cdx"
TO = "20191231235959"

def q(params, timeout=60):
    url = BASE + "?" + urllib.parse.urlencode(params)
    t0 = time.time()
    try:
        import urllib.request
        req = urllib.request.Request(url, headers={"User-Agent": "shurik-hazfalafel-recovery/1.0"})
        with urllib.request.urlopen(req, timeout=timeout) as r:
            body = r.read().decode("utf-8", "replace")
            return {"status": r.status, "body": body, "secs": round(time.time()-t0, 1)}
    except Exception as e:
        return {"error": repr(e)[:120], "secs": round(time.time()-t0, 1)}

STEM = sys.argv[1] if len(sys.argv) > 1 else "tumblr_ndozw9K7Dz1r3it8zo1"
hosts = [str(h) for h in range(1, 51)]

def probe(h):
    return h, q({"url": f"{h}.media.tumblr.com/{STEM}_500.jpg", "output": "json", "to": TO, "limit": "5", "filter": "statuscode:200"})

with ThreadPoolExecutor(max_workers=5) as ex:
    for h, res in ex.map(probe, hosts):
        b = res.get("body", "")
        print(h, res.get("status"), res.get("error", ""), (b[:200].replace("\n", " ") if b else ""), res.get("secs"), flush=True)
